<!doctype html><html lang="id"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Threads Tools</title>
<style>
:root{font:14px system-ui;color:#e8eeff;background:#0a1020}*{box-sizing:border-box}body{margin:0}header{padding:18px 4%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #2c3c59}nav{display:flex;gap:14px;flex-wrap:wrap;padding:16px 4%;position:sticky;top:0;background:#0a1020}a{color:#92bcff}main{max-width:1400px;margin:auto;padding:0 4% 70px}section{margin:24px 0;padding:20px;background:#131d33;border:1px solid #273653;border-radius:16px}h1,h2,h3{margin:0 0 14px}p{color:#aebcda}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.card{padding:16px;background:#1b2943;border-radius:12px;min-width:0}.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}input,select,textarea,button{font:inherit;padding:9px;border-radius:8px;max-width:100%}input,select,textarea{background:#0c1529;border:1px solid #3a4e70;color:#eef3ff}textarea{width:100%;min-height:92px}button{background:#578ce8;border:0;color:white;cursor:pointer}button:hover{background:#75a8f8}form{margin:7px 0}.muted{color:#b5bfd4;font-size:12px}.badge{border:1px solid #6687b8;border-radius:99px;padding:2px 8px;font-size:11px;white-space:nowrap}img{max-width:110px;max-height:90px;object-fit:cover;border-radius:6px}label{display:block;margin:8px 0}summary{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #33415d;text-align:left;padding:8px}.scroll{overflow:auto}@media(max-width:620px){header{align-items:start;gap:10px}nav{position:static}.card{padding:12px}}
