<section id="campaigns"><h2>Campaigns</h2><form method="post" action="/campaigns" class="row">@csrf<input name="name" placeholder="Nama campaign" required><input name="product_name" placeholder="Produk"><input name="notes" placeholder="Catatan"><button>Buat Campaign</button></form><div class="grid">@foreach($campaigns as $c)<div class="card"><h3>{{$c->name}}</h3><p>{{$c->product_name}}</p><form action="/campaigns/{{$c->id}}/duplicate" method="post">@csrf<label>Pilih akun untuk draft:</label><div class="row">@foreach($accounts as $a)<label><input type="checkbox" name="account_ids[]" value="{{$a->id}}"> {{'@'.($a->username??$a->id)}}</label>@endforeach</div><button>Duplicate to selected</button></form></div>@endforeach</div></section>
<section id="media"><h2>Media Library</h2><form action="/media" method="post" enctype="multipart/form-data" class="row">@csrf<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required><select name="campaign_id"><option value="">Umum</option>@foreach($campaigns as $c)<option value="{{$c->id}}">{{$c->name}}</option>@endforeach</select><button>Upload</button></form><div class="row">@foreach($media as $m)<div class="card"><img src="/media/{{$m->id}}" alt="{{$m->original_name}}"><p>#{{$m->id}} {{$m->original_name}}</p></div>@endforeach</div></section>
<section id="posts"><h2>Post Editor</h2><p>Simpan perubahan lalu approve sebelum masuk queue. Media diurutkan sesuai urutan ID yang dipilih.</p><div class="grid">@foreach($posts as $p)<div class="card"><div class="row"><h3>#{{$p->id}} {{'@'.($p->username??$p->threads_account_id)}}</h3><span class="badge">{{$p->status}}</span></div><p>Campaign #{{$p->campaign_id}} · {{$p->account_status}}</p>@if(in_array($p->status,['DRAFT','READY','APPROVED','FAILED']))<form action="/posts/{{$p->id}}" method="post">@csrf<textarea name="caption" placeholder="Caption" required>{{$p->caption}}</textarea><label>Schedule (kosong = segera) <input type="datetime-local" name="scheduled_at" value="{{ $p->scheduled_at ? \Illuminate\Support\Carbon::parse($p->scheduled_at)->format('Y-m-d\TH:i') : '' }}"></label><label>Media (Ctrl/⌘ untuk memilih beberapa)</label><select name="media_ids[]" multiple size="4" style="width:100%">@foreach($media as $m)<option value="{{$m->id}}">#{{$m->id}} {{$m->original_name}}</option>@endforeach</select><button>Simpan Draft</button></form>@endif
