<section id="telegram"><h2>Telegram</h2><div class="grid"><div class="card"><h3>Groups</h3><form action="/telegram/groups" method="post">@csrf<input name="name" placeholder="Group name" required><input name="chat_id" placeholder="-100..." required><button>Tambah Group</button></form>@foreach($groups as $g)<p>{{$g->name}} · {{$g->chat_id}}</p>@endforeach</div><div class="card"><h3>Community Templates</h3><form action="/telegram/templates" method="post">@csrf<input name="name" placeholder="Judul" required><select name="kind"><option>FAQ</option><option>ANNOUNCEMENT</option><option>SIMULATION</option></select><textarea name="body" placeholder="Konten" required></textarea><button>Simpan</button></form>@foreach($templates as $t)<details><summary>{{$t->name}} · {{$t->kind}}</summary><p style="white-space:pre-wrap">{{$t->body}}</p><form action="/telegram/templates/{{$t->id}}/send" method="post">@csrf<select name="group_id">@foreach($groups as $g)<option value="{{$g->id}}">{{$g->name}}</option>@endforeach</select><button>Kirim</button></form></details>@endforeach</div></div><h3>Verified Transaction Feed</h3><p>Hanya webhook ber-HMAC dari website order setelah status PAID yang dapat membuat entri. Seluruhnya perlu approval.</p><div class="grid">@foreach($feed as $f)<div class="card"><b>Order #{{$f->external_order_id}}</b><p>{{$f->product}} · Rp{{number_format($f->amount_idr,0,',','.')}}</p><span class="badge">{{$f->status}}</span>@if($f->status==='PENDING_APPROVAL')<form action="/telegram/feed/{{$f->id}}/approve" method="post">@csrf<button>Approve</button></form>@elseif($f->status==='APPROVED')<form action="/telegram/feed/{{$f->id}}/send" method="post">@csrf<button>Kirim ke Telegram</button></form>@endif @if($f->last_error)<p>{{$f->last_error}}</p>@endif</div>@endforeach</div></section>
<section id="logs"><h2>Activity Log</h2><div class="scroll"><table><thead><tr><th>Waktu</th><th>Post</th><th>Step</th><th>Status</th><th>Detail</th></tr></thead><tbody>@foreach($logs as $l)<tr><td>{{$l->created_at}}</td><td>{{$l->campaign_post_id}}</td><td>{{$l->step}}</td><td>{{$l->status}}</td><td>{{$l->detail}}</td></tr>@endforeach</tbody></table></div></section>
